const NAV_SETS = ['Navigation Bar Item', 'Navigation Drawer Item'];
const BY_NEW = {}; for (const k in ICONS) BY_NEW[ICONS[k].name] = k;

// ---------------------------------------------------------------- log
let LOG = [], ERRLIST = [], STATS = {};
function errMsg(e) { return e && e.message ? e.message : String(e); }
function say(msg, extra) { LOG.push({ t: Date.now(), msg: msg }); try { console.log('[Icones] ' + msg); } catch (e) {} try { penpot.ui.sendMessage(Object.assign({ type: 'progress', msg: msg }, extra || {})); } catch (e) {} }
function err(where, e, extra) { ERRLIST.push(Object.assign({ where: where, message: errMsg(e) }, extra || {})); }
function safe(fn, d) { try { const v = fn(); return v === undefined ? d : v; } catch (e) { return d; } }
function tryDo(where, fn, extra) { try { fn(); return true; } catch (e) { err(where, e, extra); return false; } }
const sleep = (ms) => (typeof setTimeout === 'function' ? new Promise(r => setTimeout(r, ms)) : Promise.resolve());
async function settle() { try { if (typeof penpot.waitForLayoutUpdate === 'function') { await penpot.waitForLayoutUpdate(10000); return; } } catch (e) {} await sleep(200); }
const kidsOf = (s) => safe(() => s.children, []) || [];
const pagesOf = () => safe(() => penpot.currentFile.pages, []) || [];

function fileCheck() {
  const f = safe(() => penpot.currentFile, null);
  if (!f) return { ok: false, why: 'Nenhum arquivo aberto.' };
  const id = safe(() => f.id, ''), name = safe(() => f.name, '');
  if (id !== LIB_FILE_ID && name !== LIB_FILE) return { ok: false, why: 'Este plugin só roda no arquivo "' + LIB_FILE + '". O arquivo aberto é "' + name + '". Nada foi alterado.' };
  return { ok: true, name: name, id: id };
}

// ---------------------------------------------------------------- geometria
function scaleD(d, k, dx, dy) {
  let i = 0;
  return d.trim().split(/\s+/).map(t => { if (/^[A-Z]$/.test(t)) { i = 0; return t; } const v = parseFloat(t) * k + (i++ % 2 === 0 ? dx : dy); return String(Math.round(v * 1000) / 1000); }).join(' ');
}
const nums = (d) => (String(d || '').match(/-?\d*\.?\d+(?:e-?\d+)?/gi) || []).map(Number);
function sameD(a, b) { const x = nums(a), y = nums(b); if (x.length !== y.length) return false; for (let i = 0; i < x.length; i++) if (Math.abs(x[i] - y[i]) > 0.05) return false; return true; }

// ---------------------------------------------------------------- leitura
// marca guardada no componente na 1ª rodada (o nome muda; a marca não). Sem marca, decide pelo nome.
const MARK = 'anotaIconeAntigo';
function iconComps() {
  const out = { byId: {}, old: {}, done: {}, filled: {} };
  const all = (safe(() => penpot.library.local.components, []) || []).filter(c => /^icon$/i.test(String(safe(() => c.path, '')).trim()));
  const converted = all.some(c => { const n = safe(() => c.name, ''); return BY_NEW[n] && !ICONS[n]; });
  for (const c of all) {
    const name = safe(() => c.name, ''); const mark = safe(() => c.getPluginData(MARK), '');
    let old = null;
    if (mark && ICONS[mark]) old = mark;
    else if (/_fill$/.test(name) && FILLED[name.replace(/_fill$/, '')]) { const b = name.replace(/_fill$/, ''); out.filled[b] = c; out.byId[c.id] = { comp: c, filledOf: b, state: 'filled' }; continue; }
    else if (converted) old = BY_NEW[name] || (ICONS[name] ? name : null);
    else old = ICONS[name] ? name : (BY_NEW[name] || null);
    if (!old) continue;
    const state = name === ICONS[old].name && (converted || mark) ? 'new' : 'old';
    if (state === 'old') out.old[old] = c; else out.done[old] = c;
    out.byId[c.id] = { comp: c, old: old, state: state };
  }
  return out;
}
function paths(head) { return kidsOf(head).filter(k => safe(() => k.type, '') === 'path'); }
function isIconHead(s, ic) {
  if (safe(() => s.type, '') !== 'board') return null;
  const c = safe(() => s.component(), null); const info = c ? ic.byId[c.id] : null;
  if (!info) return null;
  const ks = kidsOf(s); if (!ks.length || ks.some(k => safe(() => k.type, '') !== 'path')) return null;
  return info;
}
function fillFromStroke(st) { const o = { fillColor: st.strokeColor, fillOpacity: st.strokeOpacity == null ? 1 : st.strokeOpacity }; if (st.strokeColorRefId) { o.fillColorRefId = st.strokeColorRefId; if (st.strokeColorRefFile) o.fillColorRefFile = st.strokeColorRefFile; } return clean(o); }
