        const base = info.filledOf || (ICONS[info.old] && ICONS[info.old].name);
        heads.push({ page: p, s: s, id: s.id, comp: c, info: info, main: isMain, base: base, paint: paintOf(s), size: safe(() => s.width, 24),
          parent: safe(() => s.parent, null), index: kidsOf(safe(() => s.parent, null)).findIndex(k => k.id === s.id), active: activeNav(s, c.id), inMain: !!safe(() => s.isComponentMainInstance(), false), nPaths: paths(s).length });
