// ---------------------------------------------------------------- escrita
let running = false;
async function activate(page) { if (safe(() => penpot.currentPage.id, null) === page.id) return; await penpot.openPage(page); for (let i = 0; i < 100 && safe(() => penpot.currentPage.id, null) !== page.id; i++) await sleep(40); }
function onSurfaceFill() {
  const c = (safe(() => penpot.library.local.colors, []) || []).find(x => safe(() => x.name, '') === 'onSurface');
  return c ? cleanFill(c.asFill()) : { fillColor: '#FAFAFA', fillOpacity: 1 };
}
function expectedD(h, compD) { const k = (safe(() => h.s.width, 24)) / 24; return scaleD(compD, k, safe(() => h.s.x, 0), safe(() => h.s.y, 0)); }
// desenha o ícone na cabeça h: 1 caminho com o desenho novo e a cor guardada; caminhos que sobraram somem
function redraw(h, d, paint) {
  const ps = paths(h.s); if (!ps.length) { err('sem caminho', new Error('cabeça sem caminho'), { id: h.id }); return false; }
  const p0 = ps[0]; let ok = true;
  ok = tryDo('desenho', () => { p0.d = expectedD(h, d); }, { id: h.id }) && ok;
  ok = tryDo('cor', () => { p0.fills = [paint]; }, { id: h.id }) && ok;
  ok = tryDo('traço', () => { p0.strokes = []; }, { id: h.id }) && ok;
  if (h.main) tryDo('nome caminho', () => { p0.name = 'fill 1'; });
  if (safe(() => p0.hidden, false)) tryDo('mostrar', () => { p0.hidden = false; });
  for (const extra of ps.slice(1)) {
    if (h.main) tryDo('apagar caminho extra', () => extra.remove(), { id: h.id });
    else if (!safe(() => extra.hidden, false)) tryDo('esconder caminho extra', () => { extra.hidden = true; }, { id: h.id });
  }
  STATS.desenhados++;
  return ok;
}
async function makeFilled(base, iconsPage, wrap, sampleTile) {
  await activate(iconsPage);
  const b = penpot.createBoard(); b.name = 'Icon / ' + base + '_fill'; b.resize(24, 24); tryDo('clip', () => { b.clipContent = false; }); b.fills = [];
  const p = penpot.createPath(); p.d = scaleD(FILLED[base], 1, b.x, b.y); p.name = 'fill 1'; p.fills = [onSurfaceFill()]; p.strokes = [];
  b.appendChild(p); tryDo('constraints', () => { p.constraintsHorizontal = 'scale'; p.constraintsVertical = 'scale'; });
  const comp = penpot.library.local.createComponent([b]);
  const main = safe(() => comp.mainInstance(), null) || b;
  if (wrap) {
    const tile = penpot.createBoard(); tile.name = 'Tile ' + base + '_fill';
    tryDo('tile', () => {
      tile.resize(112, 96); tile.fills = (safe(() => sampleTile.fills, null) || []).map(cleanFill); tile.borderRadius = safe(() => sampleTile.borderRadius, 12) || 12;
      const fl = tile.addFlexLayout(); fl.dir = 'column'; fl.rowGap = 12; fl.columnGap = 12; fl.alignItems = 'center'; fl.justifyContent = 'center';
      fl.topPadding = 20; fl.rightPadding = 4; fl.bottomPadding = 12; fl.leftPadding = 4;
    });
    tryDo('tile no grid', () => wrap.appendChild(tile));
    tryDo('ícone no tile', () => tile.appendChild(main));
    const sampleText = kidsOf(sampleTile).find(k => safe(() => k.type, '') === 'text');
    const t = penpot.createText(base + '_fill');
    if (t) tryDo('texto do tile', () => {
      t.name = 'Name';
      const ty = (safe(() => penpot.library.local.typographies, []) || []).find(x => safe(() => x.name, '') === 'bodySmall');
      if (ty) ty.applyToText(t);
      if (sampleText) t.fills = (safe(() => sampleText.fills, []) || []).map(cleanFill);
      tile.appendChild(t);
    });
  }
  STATS.preenchidosCriados++;
  return comp;
}
async function apply() {
  if (running) return; running = true; LOG = []; ERRLIST = []; STATS = { desenhados: 0, renomeados: 0, preenchidosCriados: 0, trocasAtivas: 0, conferidos: 0, conferenciaFalhou: 0 };
  const t0 = Date.now(); const startPage = safe(() => penpot.currentPage, null);
  try {
    const fc = fileCheck(); if (!fc.ok) { say(fc.why, { finished: true, failed: true, log: { tipo: 'troca', recusado: fc.why } }); return; }
    try { if (penpot.flags) penpot.flags.naturalChildOrdering = true; } catch (e) {}
    const first = scan();
    if (!Object.keys(first.ic.old).length && !Object.keys(first.ic.done).length) throw new Error('Nenhum componente "Icon / ..." encontrado. Nada foi alterado.');
    say('Achei ' + Object.keys(first.ic.old).length + ' ícones antigos, ' + Object.keys(first.ic.done).length + ' já trocados, ' + first.heads.filter(h => !h.main).length + ' cópias.');
    try { await penpot.currentFile.saveVersion('Antes dos ícones Material'); say('Versão salva: "Antes dos ícones Material".'); } catch (e) { err('saveVersion', e); say('Não consegui salvar a versão (sigo mesmo assim; dá para desfazer pelo histórico).'); }
    for (const id in first.ic.byId) { const x = first.ic.byId[id]; if (x.old) tryDo('marca ' + x.old, () => x.comp.setPluginData(MARK, x.old)); }
    const ON = onSurfaceFill();
    // 1) desenho novo em todas as cabeças (principal e cópias), página por página
    const byPage = {}; for (const h of first.heads) (byPage[h.page.id] = byPage[h.page.id] || { page: h.page, list: [] }).list.push(h);
    for (const pid in byPage) {
      const g = byPage[pid]; await activate(g.page);
      g.list.sort((a, b) => (b.main ? 1 : 0) - (a.main ? 1 : 0));
      let n = 0;
      for (const h of g.list) {
        const d = h.info.state === 'filled' ? FILLED[h.info.filledOf] : ICONS[h.info.old].d;
        redraw(h, d, h.main ? ON : (h.paint || ON));
        if (++n % 40 === 0) await sleep(30);
      }
      say('Página "' + safe(() => g.page.name, '') + '": ' + g.list.length + ' ícones redesenhados.');
      await settle();
    }
    // 2) nomes dos componentes e dos tiles
    let iconsPage = null, wrap = null, sampleTile = null;
    for (const old in first.ic.old) {
      const c = first.ic.old[old], nw = ICONS[old].name; const main = safe(() => c.mainInstance(), null);
      const pg = main ? first.heads.find(h => h.id === main.id) : null; if (pg) { await activate(pg.page); iconsPage = pg.page; }
      if (tryDo('renomear ' + old, () => { c.name = nw; })) STATS.renomeados++;
      if (main) {
        tryDo('nome principal ' + old, () => { if (String(main.name).indexOf('/') >= 0) main.name = 'Icon / ' + nw; else main.name = nw; });
        const tile = safe(() => main.parent, null);
        if (tile && /^Tile /.test(safe(() => tile.name, ''))) {
          tryDo('nome tile', () => { tile.name = 'Tile ' + nw; });
          const tx = kidsOf(tile).find(k => safe(() => k.type, '') === 'text'); if (tx) tryDo('texto tile', () => { tx.characters = nw; });
          wrap = safe(() => tile.parent, null); sampleTile = tile;
        }
      }
    }
    if (!iconsPage) { const anyMain = first.heads.find(h => h.main); if (anyMain) { iconsPage = anyMain.page; sampleTile = safe(() => anyMain.s.parent, null); wrap = safe(() => sampleTile.parent, null); } }
    // texto da página de ícones que ainda fala de Lucide
    if (iconsPage) { await activate(iconsPage); const walk = (s) => { for (const k of kidsOf(s)) { if (safe(() => k.type, '') === 'text') { const tx = safe(() => k.characters, ''); if (/Lucide/.test(tx)) tryDo('texto Icons', () => { k.characters = 'Ícones Material Symbols (Google), estilo Rounded: peso 400, sem preenchimento, grade de 24 dp (tamanho padrão do Material 3). Cada ícone é um componente (Icon / nome) e é usado como cópia dentro dos botões, itens e barras. Licença Apache 2.0.'; }); else if (/Ícones preenchidos \(home, clock/.test(tx)) tryDo('nota Icons', () => { k.characters = 'Versões preenchidas (nome_fill: home, fitness_center, schedule, group, person) só aparecem no item ativo da navegação. O ícone menu é usado na Navigation Rail.'; }); } else walk(k); } }; walk(iconsPage.root); }
    // 3) versões preenchidas
    const ic2 = iconComps(); const filledComp = Object.assign({}, ic2.filled);
    for (const base in FILLED) { if (filledComp[base]) continue; try { filledComp[base] = await makeFilled(base, iconsPage, wrap, sampleTile); } catch (e) { err('criar preenchido ' + base, e); } }
    say('Versões preenchidas: ' + Object.keys(filledComp).length + ' (' + STATS.preenchidosCriados + ' novas).');
    await settle();
    // 4) itens ativos da navegação usam a versão preenchida (cópias primeiro, depois os principais)
    const second = scan();
    const todo = second.heads.filter(h => h.active && !h.main && h.info.state !== 'filled' && FILLED[h.base] && filledComp[h.base]);
    todo.sort((a, b) => (a.inMain ? 1 : 0) - (b.inMain ? 1 : 0));
    const swapped = []; const seen = new Set(); const PAINT_AFTER = {};
    for (const h of todo) {
      await activate(h.page);
      const target = filledComp[h.base]; const paint = first.heads.find(x => x.id === h.id);
      const keep = { parent: h.parent, index: h.index, size: h.size, paint: (paint && paint.paint) || h.paint || ON, target: target, page: h.page, base: h.base };
      if (!tryDo('trocar ' + h.base, () => h.s.swapComponent(target), { id: h.id })) continue;
      swapped.push(keep);
    }
    for (const k of swapped) {
      await activate(k.page);
      let neu = null; const t1 = Date.now();
      while (!neu && Date.now() - t1 < 5000) { neu = kidsOf(k.parent).find(x => safe(() => x.component().id, null) === k.target.id && !seen.has(x.id)); if (!neu) await sleep(50); }
      if (!neu) { err('troca não apareceu', new Error(k.base)); continue; }
      seen.add(neu.id);
      const h = { s: neu, id: neu.id, main: false };
      tryDo('nome troca', () => { neu.name = 'Icon'; });
      if (Math.abs(safe(() => neu.width, 24) - k.size) > 0.01) tryDo('tamanho troca', () => neu.resize(k.size, k.size));
      redraw(h, FILLED[k.base], k.paint); STATS.trocasAtivas++; PAINT_AFTER[neu.id] = k.paint;
    }
    say('Itens ativos com ícone preenchido: ' + STATS.trocasAtivas + ' de ' + todo.length + '.');
    await settle(); await sleep(300);
    // 5) conferência: lê tudo de novo
    const fin = scan(); const bad = [];
    const leftOld = Object.keys(fin.ic.old);
    for (const h of fin.heads) {
      const d = h.info.state === 'filled' ? FILLED[h.info.filledOf] : (h.info.old && ICONS[h.info.old].d);
      const vis = paths(h.s).filter(p => !safe(() => p.hidden, false));
      const p0 = vis[0]; const why = [];
      if (vis.length !== 1) why.push(vis.length + ' caminhos visíveis');
      if (p0 && !sameD(safe(() => p0.d, ''), expectedD(h, d))) why.push('desenho diferente');
      if (p0 && (safe(() => p0.strokes, []) || []).length) why.push('ainda tem traço');
      const f = p0 && (safe(() => p0.fills, []) || [])[0];
      if (!f) why.push('sem cor');
      const was = first.heads.find(x => x.id === h.id) || (PAINT_AFTER[h.id] ? { paint: PAINT_AFTER[h.id] } : null);
      if (f && was && was.paint && !h.main && (was.paint.fillColorRefId ? f.fillColorRefId !== was.paint.fillColorRefId : String(f.fillColor).toLowerCase() !== String(was.paint.fillColor).toLowerCase())) why.push('cor mudou');
      if (h.active && !h.main && FILLED[h.base] && h.info.state !== 'filled') why.push('item ativo sem versão preenchida');
      STATS.conferidos++;
      if (why.length) { STATS.conferenciaFalhou++; bad.push({ pagina: safe(() => h.page.name, ''), icone: h.base, camada: safe(() => h.s.name, ''), id: h.id, principal: h.main, problema: why.join(', ') }); }
    }
    if (startPage) { try { await activate(startPage); } catch (e) {} }
    const secs = Math.round((Date.now() - t0) / 1000);
    const log = { tipo: 'troca', plugin: PLUGIN_BUILD, quando: new Date(t0).toISOString(), segundos: secs, api: safe(() => penpot.version, null), stats: Object.assign({}, STATS),
      antigosQueFicaram: leftOld, conferencia: { cabecas: fin.heads.length, problemas: bad }, erros: ERRLIST.slice(), passos: LOG.slice(), troca: Object.keys(ICONS).map(k => k + ' → ' + ICONS[k].name) };
    say('Concluído em ' + secs + ' s. Redesenhados: ' + STATS.desenhados + ' · renomeados: ' + STATS.renomeados + ' · preenchidos novos: ' + STATS.preenchidosCriados + ' · ativos trocados: ' + STATS.trocasAtivas +
      ' · conferidos: ' + STATS.conferidos + ' · problemas: ' + bad.length + ' · erros: ' + ERRLIST.length, { finished: true, log: log });
  } catch (e) {
    err('run', e);
    say('Falhou: ' + errMsg(e), { finished: true, failed: true, log: { tipo: 'troca', plugin: PLUGIN_BUILD, stats: STATS, erros: ERRLIST.slice(), passos: LOG.slice() } });
  } finally { running = false; }
}

penpot.ui.open('Anota Treino — Ícones Material', UI_URL, { width: 360, height: 560 });
penpot.ui.onMessage((msg) => {
  if (!msg) return;
  if (msg.type === 'check') { const c = fileCheck(); penpot.ui.sendMessage({ type: 'check', ok: c.ok, why: c.why, name: c.name, plugin: PLUGIN_BUILD }); }
  if (msg.type === 'diagnose') { if (running) return; let out; try { out = diagnose(); } catch (e) { out = { tipo: 'diagnostico', falhou: errMsg(e) }; } penpot.ui.sendMessage({ type: 'diagnose', log: out }); }
  if (msg.type === 'apply') apply();
});
